};
typedef struct Set set;
void init(set *a)
{
    scanf("%d",&(a->n));
    a->ar=(int *)calloc(a->n,sizeof(int));
    for(int i=0;i<(a->n);i++)
    {
        scanf("%d",&(a->ar[i]));
    }
}
int min(int a,int b)
{
    if(a<b)
        return a;
    else return b;
}
int intersection(set *a,set *b,int *ans)
{
    int k=0;
    ans=(int *)calloc(min(a->n,b->n),sizeof(int));
    for(int i=0;i<(a->n);i++)
    {
        for(int j=0;j<b->n;j++)
        {
            if(a->ar[i]==b->ar[j])
            {
                ans[k]=a->ar[i];
                k++;
            }
        }
    }
    return k;
}

